(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.45)*8;
  const sx = x+wx, sy = y+wy;
  const dwx = Math.sin(sx*0.03+sy*0.02+t*0.7)*6 + Math.cos(sy*0.025-sx*0.015+t*0.9)*5;
  const dwy = Math.cos(sx*0.025-sy*0.03+t*0.6)*6 + Math.sin(sy*0.02+sx*0.018-t*0.8)*5;
  const dx = sx+dwx, dy = sy+dwy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.6],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*45, 0.13, 1.8, 1.3]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const wv = Math.sin(d*f-t*sp)*w;
    aS += wv;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
  }
  const n = 8;
  const act=aS/n, inh=iS/n, cor=cS/n;
  const bg = (Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2
    + Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2
    + Math.sin(dx*0.08+dy*0.06+t*1.5)*0.15;
  const dist = Math.sqrt((dx-cx)**2+(dy-cy)**2), ang = Math.atan2(dy-cy, dx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.03-ang*5+t*1.8)*0.5+Math.sin(dist*0.06+ang*2-t*0.9)*0.5)*0.28;
  const pulse = Math.sin(t*0.8)*0.15+Math.sin(t*1.3+1)*0.1;
  const reaction = Math.tanh((act-inh*0.65+cor*0.2+bg*0.3+spiral+pulse)*2.2);
  const cell = Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5
    +Math.sin(dx*0.22-dy*0.18+t*1.4)*0.3)*1.5)*0.3;
  const fine = Math.sin(dx*0.35+t*3)*Math.sin(dy*0.35-t*2.5)*0.08*reaction;
  const glow = Math.exp(-dist*0.008)*(Math.sin(t*0.5)*0.1+0.1);
  const blend = reaction*0.6+cell*0.2+fine+glow;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const pal = [
    [6,12,52],[12,42,88],[18,78,108],[25,125,118],
    [65,168,135],[185,185,80],[215,145,65],[195,90,72],
    [155,52,68],[95,28,72],[45,18,62],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65?1.12:1.0;
  const core = Math.abs(reaction)>0.85?1.08:1.0;
  const m = lum*edge*core;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
